from pathlib import Path
import numpy as np
import soundfile as sf
import soxr


def _derive_working(raw: Path, dest: Path, working_format: str) -> None:
    """48k/24 mono working copy: strongest-channel select (not averaging — the
    Chromium stereo-silent-R trap) then soxr PCM resample to 48 kHz, written 24-bit."""
    data, sr = sf.read(str(raw), dtype="float32", always_2d=False)
    if data.ndim > 1:
        rms = np.sqrt((data.astype(np.float64) ** 2).mean(axis=0))
        mono = data[:, int(np.argmax(rms))]
    else:
        mono = data
    if sr != 48000:
        mono = soxr.resample(mono, sr, 48000)
    sf.write(str(dest), mono, 48000, subtype="PCM_24",
             format="FLAC" if working_format == "flac" else "WAV")
